/**
 * n8n Code node — wf6 step 0: build today's persona posting slots.
 *
 * Output: one item per persona slot, with scheduled_at, length_band, tone, format,
 *         time_of_day, psychology_techniques.
 *
 * Rules:
 *  - Slots are placed at persona_slot_hours (defaults [7, 11, 16, 21] Kuala Lumpur time).
 *  - Each slot is jittered ±persona_jitter_min (default 22 min) for irregularity.
 *  - persona_skip_prob (default 8%) chance a slot is dropped — irregularity.
 *  - Length-band mix is configurable: micro/mid/long (default 25/60/15).
 *  - Tone is drawn from a persona-appropriate subset (no enthusiast, no corporate_parody —
 *    those read like influencers or parody accounts).
 *  - Format is drawn from persona-appropriate formats (confession, one_liner, chat_narration,
 *    overheard, list_of_three, question_hook) — no honest_review/diary/myth_bast/product frames.
 *  - Media type is always TEXT for persona posts (no product photos to attach).
 *  - Time-of-day affinity: morning slots prefer commute/breakfast topics, afternoon prefers
 *    petua/household, evening prefers food/family/reflection.
 *  - Psychology techniques: 1-2 techniques assigned per slot from the psychology seed pool,
 *    weighted toward persona-appropriate techniques (reciprocity, belonging, participation).
 */

const ALLOWED_TONES = ['deadpan', 'gaul', 'warm_sibling', 'chaotic', 'minimal', 'makcik'];
const ALLOWED_FORMATS = ['confession', 'one_liner', 'chat_narration', 'overheard',
                         'list_of_three', 'question_hook', 'pov', 'rant_bite', 'petua'];

// Time-of-day mapping from slot hours
const HOUR_TO_TIME_OF_DAY = {
  7: 'morning',
  11: 'midday',
  16: 'afternoon',
  21: 'evening',
};

// Psychology techniques suitable for persona posts (from seed_techniques_psychology.sql)
const PERSONA_PSYCHOLOGY_TECHNIQUES = [
  'reciprocity_first',       // give value before asking
  'liking_through_specificity', // name one specific shared detail
  'unity_shared_identity',   // name the group the reader belongs to
  'punctuation_signals_tone', // period = serious, no period = casual
  'clarity_over_cleverness', // one idea per sentence
  'write_like_you_talk',     // BM pasar contractions
  'cut_ruthlessly',          // every sentence must earn its place
  'participation_loop',      // ask for specific input
  'belonging_signal',        // "kita" for struggles, "saya" for wins
];

// Technique weights by time of day (some techniques work better at certain times)
const TECHNIQUE_TIME_WEIGHTS = {
  morning:   { reciprocity_first: 1.2, belonging_signal: 1.0, participation_loop: 0.8 },
  midday:    { clarity_over_cleverness: 1.3, write_like_you_talk: 1.2, cut_ruthlessly: 1.1 },
  afternoon: { reciprocity_first: 1.3, liking_through_specificity: 1.2, participation_loop: 1.1 },
  evening:   { belonging_signal: 1.4, unity_shared_identity: 1.3, participation_loop: 1.2 },
};

const DEFAULT_SETTINGS = {
  persona_slot_hours: [7, 11, 16, 21],
  persona_jitter_min: 22,
  persona_skip_prob: 0.08,
  persona_micro_pct: 0.25,
  persona_mid_pct: 0.60,
  persona_long_pct: 0.15,
  timezone: 'Asia/Kuala_Lumpur',
};

function pickWeighted(rng, pairs) {
  const total = pairs.reduce((s, p) => s + p.w, 0);
  let r = rng() * total;
  for (const p of pairs) { r -= p.w; if (r <= 0) return p.v; }
  return pairs[pairs.length - 1].v;
}

function buildPersonaSlots(opts = {}) {
  const settings = { ...DEFAULT_SETTINGS, ...(opts.settings ?? {}) };
  const now = new Date();
  const tz = settings.timezone ?? 'Asia/Kuala_Lumpur';

  // We run at 03:30 (after wf2's 03:00 product generation finishes), so slots are for TODAY or
  // TOMORROW depending on hour. For simplicity: if before 05:00 local, generate for today;
  // otherwise for tomorrow.
  const d = new Date(now);
  // Compute local hour in timezone.
  const localHourStr = new Intl.DateTimeFormat('en-US', {
    hour: '2-digit', hour12: false, timeZone: tz,
  }).format(d);
  const localHour = Number(localHourStr) % 24;
  if (localHour >= 5) d.setDate(d.getDate() + 1);
  // Set to midnight local time in the timezone.
  const parts = new Intl.DateTimeFormat('en-CA', {
    year: 'numeric', month: '2-digit', day: '2-digit', timeZone: tz,
  }).formatToParts(d);
  const y = Number(parts.find(p => p.type === 'year').value);
  const m = Number(parts.find(p => p.type === 'month').value) - 1;
  const day = Number(parts.find(p => p.type === 'day').value);
  const dayStart = new Date(Date.UTC(y, m, day, 0, 0, 0));
  // UTC offset for the timezone at that date — this gives us the right UTC start.
  const tzOffsetMs = (() => {
    const dtf = new Intl.DateTimeFormat('en-US', {
      timeZone: tz, hour12: false, year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
    });
    const parts2 = dtf.formatToParts(new Date(Date.UTC(y, m, day, 12, 0, 0)));
    const obj = {};
    for (const p of parts2) obj[p.type] = Number(p.value);
    const asUtc = Date.UTC(obj.year, obj.month - 1, obj.day, obj.hour % 24, obj.minute, obj.second);
    return asUtc - Date.UTC(obj.year, obj.month - 1, obj.day, 12, 0, 0);
  })();
  const localMidnight = new Date(dayStart.getTime() - tzOffsetMs);

  const slots = [];
  const hours = settings.persona_slot_hours;
  for (let i = 0; i < hours.length; i++) {
    if (Math.random() < (settings.persona_skip_prob ?? 0.08)) continue;

    const jitter = Math.round((Math.random() * 2 - 1) * (settings.persona_jitter_min ?? 22));
    const t = new Date(localMidnight);
    t.setHours(hours[i], 0, 0, 0);
    t.setMinutes(t.getMinutes() + jitter);
    t.setSeconds(Math.floor(Math.random() * 60));

    const r = Math.random();
    let length_band = 'mid';
    if (r < settings.persona_micro_pct) length_band = 'micro';
    else if (r < settings.persona_micro_pct + settings.persona_mid_pct) length_band = 'mid';
    else length_band = 'long';

    // Tone: simple uniform draw from allowed set. Bandit scoring will update post-hoc via
    // wf4 extension — we extend topic bandit first; tone selection stays uniform for personas
    // until we have enough samples per tone on persona posts to learn.
    const tone = ALLOWED_TONES[Math.floor(Math.random() * ALLOWED_TONES.length)];
    const format = ALLOWED_FORMATS[Math.floor(Math.random() * ALLOWED_FORMATS.length)];

    // Time of day (from hour)
    const time_of_day = HOUR_TO_TIME_OF_DAY[hours[i]] || 'afternoon';

    // Psychology techniques (1-2 techniques, weighted by time of day)
    const techniqueCount = Math.random() < 0.3 ? 2 : 1; // 30% chance of 2 techniques
    const psychology_techniques = pickPersonaTechniques(time_of_day, techniqueCount);

    slots.push({
      slot_index: i,
      scheduled_at: t.toISOString(),
      length_band,
      tone,
      format,
      time_of_day,
      psychology_techniques,
      angle: 'utility',           // personas aren't selling; 'utility' is "one small useful/true thing"
      sell_intensity: '0',        // never any CTA
      media_type: 'TEXT',
      is_carousel: false,
      reply_delay_sec: 0,
      purpose: 'persona',
      timezone: tz,
    });
  }

  // Never produce zero persona slots (guards against 8% skip rolling all 4 slots).
  if (slots.length === 0) {
    const t = new Date(localMidnight);
    t.setHours(20, 12, Math.floor(Math.random() * 60), 0);
    slots.push({
      slot_index: 0, scheduled_at: t.toISOString(),
      length_band: 'mid', tone: 'gaul', format: 'one_liner',
      time_of_day: 'evening',
      psychology_techniques: pickPersonaTechniques('evening', 1),
      angle: 'utility', sell_intensity: '0', media_type: 'TEXT',
      is_carousel: false, reply_delay_sec: 0, purpose: 'persona', timezone: tz,
    });
  }

  // Follow request posts: every 3 days during warm-up phase
  const followRequestSettings = settings.persona_follow_request || {};
  if (followRequestSettings.enabled !== false) {
    const frequencyDays = followRequestSettings.frequency_days || 3;
    const onlyDuringWarmup = followRequestSettings.only_during_warmup !== false;
    const slotHour = followRequestSettings.slot_hour ?? 19;
    const slotMinute = followRequestSettings.slot_minute ?? 30;

    // Check if we're in warm-up phase (first 30 days: 14 days warmup + 16 days ramp)
    const isWarmup = !onlyDuringWarmup || isWarmupPhase(settings);

    if (isWarmup) {
      // Check if today is a follow request day (day 0, 3, 6, 9, etc.)
      const daysSinceStart = getDaysSinceWarmupStart(settings);
      const isFollowRequestDay = daysSinceStart % frequencyDays === 0;

      if (isFollowRequestDay) {
        const t = new Date(localMidnight);
        t.setHours(slotHour, slotMinute, Math.floor(Math.random() * 60), 0);

        // Pick a random tone from allowed tones (gaul/warm_sibling/curious work well)
        const followTones = ['gaul', 'warm_sibling', 'curious', 'deadpan', 'chaotic', 'minimal'];
        const tone = followTones[Math.floor(Math.random() * followTones.length)];

        // Pick a psychology technique suited for follow requests
        const followTechniques = ['reciprocity_first', 'belonging_signal', 'participation_loop', 'liking_through_specificity'];
        const psychology_techniques = [followTechniques[Math.floor(Math.random() * followTechniques.length)]];

        slots.push({
          slot_index: slots.length,
          scheduled_at: t.toISOString(),
          length_band: 'short',  // follow requests are usually short
          tone,
          format: 'direct_ask',  // new format for follow requests
          time_of_day: HOUR_TO_TIME_OF_DAY[slotHour] || 'evening',
          psychology_techniques,
          angle: 'follow_request',
          sell_intensity: '0',
          media_type: 'TEXT',
          is_carousel: false,
          reply_delay_sec: 0,
          purpose: 'persona',
          timezone: tz,
        });
      }
    }
  }

  return slots;
}

/**
 * Check if we're currently in warm-up phase (first 30 days).
 */
function isWarmupPhase(settings) {
  const warmup = settings.warmup || {};
  if (!warmup.enabled || !warmup.started_at) return false;

  const startDate = new Date(warmup.started_at);
  const now = new Date();
  const daysSinceStart = Math.floor((now - startDate) / (1000 * 60 * 60 * 24));

  // Warm-up is 14 days + ramp is 16 days = 30 days total
  return daysSinceStart < 30;
}

/**
 * Get the number of days since warm-up started.
 */
function getDaysSinceWarmupStart(settings) {
  const warmup = settings.warmup || {};
  if (!warmup.started_at) return 0;

  const startDate = new Date(warmup.started_at);
  const now = new Date();
  return Math.floor((now - startDate) / (1000 * 60 * 60 * 24));
}

/**
 * Pick 1-2 psychology techniques for a persona slot, weighted by time of day.
 */
function pickPersonaTechniques(timeOfDay, count = 1) {
  const weights = TECHNIQUE_TIME_WEIGHTS[timeOfDay] || {};
  const weighted = PERSONA_PSYCHOLOGY_TECHNIQUES.map(t => ({
    name: t,
    weight: weights[t] || 1.0,
  }));

  const selected = [];
  const pool = [...weighted];

  for (let i = 0; i < count && pool.length > 0; i++) {
    const totalWeight = pool.reduce((sum, item) => sum + item.weight, 0);
    let rand = Math.random() * totalWeight;

    for (let j = 0; j < pool.length; j++) {
      rand -= pool[j].weight;
      if (rand <= 0) {
        selected.push(pool[j].name);
        pool.splice(j, 1);
        break;
      }
    }
  }

  return selected;
}

// n8n entry point: receives $json with `settings` (or falls back to defaults).
if (typeof $ !== 'undefined' && typeof $json !== 'undefined') {
  const slots = buildPersonaSlots({ settings: $json.warmup ?? $json.settings ?? {} });
  return slots.map(s => ({ json: { ...$json, ...s } }));
}

if (typeof module !== 'undefined') {
  module.exports = { buildPersonaSlots, ALLOWED_TONES, ALLOWED_FORMATS };
}

/**
 * n8n Code node — wf6 step 1: pick one persona topic via Thompson sampling.
 *
 * Mirrors bandit.js's SELECT logic, but over persona_topics rather than products/arms.
 * Now includes time-of-day affinity: prefers topics tagged for the current slot's time.
 *
 * Input $json (set by the preceding Postgres "load persona_topics" node):
 *   topics    : [{id, uid, topic, angle_hint, niche_tags, alpha, beta, n, cooldown_until, context, pinned, time_of_day}]
 *   last_n_ids: array of topic ids used in the last 7 days (avoid repetition)
 *   settings  : { bandit: { epsilon, cooldown_days, ... } }
 *   scheduled_at, timezone, time_of_day
 *
 * Output:
 *   Adds `{ topic: <chosen row>, purpose: 'persona' }` to the current item.
 */

// Gamma(k,1) via Marsaglia-Tsang (copy of bandit.js helper — kept standalone so this
// node can be pasted into n8n without requiring require()/import).
function gammaSample(k) {
  if (k < 1) return gammaSample(k + 1) * Math.pow(Math.random(), 1 / k);
  const d = k - 1 / 3, c = 1 / Math.sqrt(9 * d);
  for (;;) {
    let x, v;
    do { x = normalSample(); v = 1 + c * x; } while (v <= 0);
    v = v * v * v;
    const u = Math.random();
    if (u < 1 - 0.0331 * x * x * x * x) return d * v;
    if (Math.log(u) < 0.5 * x * x + d * (1 - v + Math.log(v))) return d * v;
  }
}
function normalSample() {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
function betaSample(a, b) {
  const x = gammaSample(Math.max(a, 0.05)), y = gammaSample(Math.max(b, 0.05));
  return x / (x + y);
}

function pickTopic({ topics, lastNIds = [], settings = {}, time_of_day = null }) {
  topics = Array.isArray(topics) ? topics : [];
  if (!topics.length) throw new Error('persona_topic_pick: no topics supplied');
  const now = Date.now();

  // Filter out topics in cooldown and topics used very recently (within last 7 days),
  // unless pinning forces one through.
  const recentlyUsed = new Set(lastNIds ?? []);
  const live = topics.filter(t => {
    if (t.pinned) return true;
    if (t.cooldown_until && new Date(t.cooldown_until).getTime() > now) return false;
    if (recentlyUsed.has(t.id)) return false;
    return true;
  });

  // Prefer the filtered pool whenever it has anything — never serve a cooled-down topic
  // unless literally nothing else exists.
  const pool = live.length >= 1 ? live : topics;

  const eps = settings?.bandit?.epsilon ?? 0.2;

  // Pinned topics get priority 70% of the time when present (operator override).
  const pinned = pool.filter(t => t.pinned);
  if (pinned.length && Math.random() < 0.7) {
    return pinned[Math.floor(Math.random() * pinned.length)];
  }

  // Time-of-day affinity: boost topics that match the current time_of_day
  const timeBoosted = pool.map(t => {
    const topicTimes = t.time_of_day || [];
    const matchesTime = !time_of_day || topicTimes.length === 0 || topicTimes.includes(time_of_day);
    return { ...t, _timeBoost: matchesTime ? 1.3 : 0.7 };
  });

  if (Math.random() < eps) {
    // EXPLORE: uniform random, biased toward least-sampled (alpha close to 1 = not yet sampled).
    const shuffled = [...timeBoosted].sort((a, b) =>
      (Number(a.alpha ?? 1) * a._timeBoost + Math.random() * 2) -
      (Number(b.alpha ?? 1) * b._timeBoost + Math.random() * 2));
    return shuffled[0];
  }

  // EXPLOIT: Thompson-sample Beta(alpha,beta) with time-of-day boost.
  let best = null, bestDraw = -1;
  for (const t of timeBoosted) {
    const a = Number(t.alpha ?? 1);
    const b = Number(t.beta ?? 1);
    // Cold-start boost for fresh topics so they get sampled at least once before the bandit
    // trusts the 0/0 prior — an (alpha=1,beta=1) draw can still land anywhere in [0,1], but
    // topics with n===0 get a tiny extra exploration push.
    let draw = Number(t.n ?? 0) === 0 ? Math.max(betaSample(a, b), 0.3 + Math.random() * 0.4)
                                        : betaSample(a, b);
    // Apply time-of-day boost
    draw *= t._timeBoost;
    if (draw > bestDraw) { bestDraw = draw; best = t; }
  }
  return best ?? pool[0];
}

// n8n entry point. n8n's Code node provides $json for the current item.
if (typeof $ !== 'undefined' && typeof $json !== 'undefined') {
  const picked = pickTopic({
    ...$json,
    time_of_day: $json.time_of_day || null,
  });
  return [{ json: { ...$json, topic: picked, purpose: 'persona' } }];
}

if (typeof module !== 'undefined') {
  module.exports = { pickTopic };
}

/**
 * n8n Code node — wf2/wf6 persona calibration.
 *
 * Input:
 *   $json.cfg.persona_snippets : [{id, domain, title, register, tags, text}]
 *   $json.tone                 : selected tone code from bandit
 *   $json.product              : product object with category_hint / enrichment (wf2 only)
 *   $json.time_of_day          : morning|midday|afternoon|evening (wf6 only)
 *   $json.purpose              : 'product' | 'persona'
 *
 * Output:
 *   Adds persona_snippets + persona_fragment for the writer prompt.
 *
 * The snippets are style/rhythm references only. They must never become facts in a product post.
 */

function shuffle(xs) {
  const a = [...xs];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/**
 * Map each tone to the registers it should prefer.
 * Extended with makcik and all persona tones.
 */
function toneRegisters(tone) {
  return ({
    warm_sibling:   ['reflective', 'conversational'],
    deadpan:        ['neutral', 'informative'],
    minimal:        ['neutral', 'informative'],
    gaul:           ['conversational', 'neutral'],
    chaotic:        ['conversational'],
    makcik:         ['conversational', 'reflective'],  // makcik = long-winded, nagging, funny details
    enthusiast:     ['conversational', 'informative'],
    corporate_parody: ['formal', 'informative'],
  })[tone] ?? ['conversational', 'neutral', 'reflective'];
}

/**
 * Time-of-day domain preferences.
 * Some domains are more relevant at certain times.
 */
function timeOfDayDomains(timeOfDay) {
  return ({
    morning:   ['commute', 'mamak', 'facebook', 'twitter'],     // commute, breakfast
    midday:    ['work', 'lowyat', 'facebook', 'twitter'],       // office, lunch
    afternoon: ['mamak', 'parenting', 'facebook', 'iium'],      // household, petua
    evening:   ['iium', 'mamak', 'facebook', 'twitter'],        // food, family, reflection
  })[timeOfDay] ?? ['facebook', 'iium', 'twitter'];
}

function clean(s) {
  return String(s ?? '').replace(/\s+/g, ' ').trim();
}

/**
 * Score a snippet for category/domain relevance to the product (wf2) or purpose (wf6).
 */
function categoryScore(snippet, product, purpose) {
  if (!product && purpose === 'persona') {
    // Persona posts don't have products — score by snippet quality only
    return 0;
  }

  const categoryText = String(
    product?.category_hint || product?.enrichment?.category || product?.name || ''
  ).toLowerCase();

  const domain = String(snippet.domain || snippet.source_domain || '').toLowerCase();
  const tags = Array.isArray(snippet.tags) ? snippet.tags.map(t => t.toLowerCase()) : [];
  const text = String(snippet.text || '').toLowerCase();

  const techKeywords = ['tech', 'gadget', 'phone', 'laptop', 'wireless', 'usb', 'charger',
    'audio', 'sound', 'camera', 'peranti', 'skrin', 'bateri', 'moniter', 'keyboard', 'router',
    'earbuds', 'smartwatch', 'monitor', 'speaker', 'drone', 'tablet'];
  const lifestyleKeywords = ['rumah', 'dapur', 'baju', 'kasut', 'skin', 'beauty', 'mask',
    'kain', 'makanan', 'decor', 'bilik', 'budak', 'anak', 'beg', 'tuala', 'periuk', 'kuali'];
  const foodKeywords = ['makan', 'nasi', 'roti', 'teh', 'kopi', 'mamak', 'char kuetiaw',
    'satay', 'laksa', 'cendol', 'mee', 'sup', 'goreng', 'curry', 'sambal'];
  const parentingKeywords = ['anak', 'baby', 'parenting', 'ibu', 'bapa', 'sekolah', 'taska',
    'budak', 'toddler', 'menyusu', 'pampers'];

  const isTechProduct = techKeywords.some(k => categoryText.includes(k));
  const isLifestyleProduct = lifestyleKeywords.some(k => categoryText.includes(k));
  const isFoodProduct = foodKeywords.some(k => categoryText.includes(k));
  const isParentingProduct = parentingKeywords.some(k => categoryText.includes(k));

  let score = 0;

  if (isTechProduct) {
    if (domain.includes('amanz') || tags.includes('tech') || tags.includes('review')) score += 4;
    if (text.includes('peranti') || text.includes('spesifikasi') || text.includes('review')) score += 2;
  }
  if (isLifestyleProduct) {
    if (domain.includes('iium') || domain.includes('facebook') || snippet.register === 'reflective') score += 3;
    if (tags.includes('household') || tags.includes('petua')) score += 2;
  }
  if (isFoodProduct) {
    if (domain.includes('mamak') || tags.includes('food')) score += 4;
  }
  if (isParentingProduct) {
    if (domain.includes('parenting') || tags.includes('parenting')) score += 4;
    if (domain.includes('iium') || snippet.register === 'reflective') score += 2;
  }

  return score;
}

/**
 * Score a snippet for time-of-day relevance.
 */
function timeOfDayScore(snippet, timeOfDay) {
  if (!timeOfDay) return 0;

  const preferredDomains = timeOfDayDomains(timeOfDay);
  const domain = String(snippet.domain || snippet.source_domain || '').toLowerCase();
  const tags = Array.isArray(snippet.tags) ? snippet.tags.map(t => t.toLowerCase()) : [];

  // Check if snippet's domain matches preferred domains
  const domainMatch = preferredDomains.some(pd => domain.includes(pd));
  if (domainMatch) return 1;

  // Check tags for time-of-day relevance
  const text = String(snippet.text || '').toLowerCase();
  const timeKeywords = {
    morning:   ['pagi', 'sarapan', 'breakfast', 'subuh', 'bangun', 'commute', 'drive', 'LRT', 'MRT'],
    midday:    ['tengahari', 'lunch', 'kerja', 'office', 'meeting', 'boss', 'kawan office'],
    afternoon: ['petang', 'dapur', 'masak', 'kemas', 'petua', 'anak', 'sekolah'],
    evening:   ['malam', 'dinner', 'makan malam', 'hujan', 'sup', 'keluarga', 'suami', 'bini'],
  };

  const keywords = timeKeywords[timeOfDay] || [];
  const keywordMatch = keywords.some(k => text.includes(k.toLowerCase()));
  if (keywordMatch) return 1;

  return 0;
}

/**
 * Score a snippet for tone/register match.
 * Makcik tone prefers longer, more detailed snippets.
 */
function toneScore(snippet, tone) {
  const preferred = toneRegisters(tone);
  let score = preferred.includes(snippet.register) ? 3 : 0;

  // Makcik tone prefers longer snippets with lots of detail
  if (tone === 'makcik') {
    const text = snippet.text || '';
    if (text.length > 300) score += 2;
    if (/\b(makcik|jiran|kawan|borak|cerita)\b/i.test(text)) score += 2;
  }

  // Deadpan/minimal prefers shorter snippets
  if (['deadpan', 'minimal'].includes(tone)) {
    const text = snippet.text || '';
    if (text.length < 200) score += 2;
  }

  // Gaul prefers conversational with slang
  if (tone === 'gaul') {
    const text = snippet.text || '';
    if (/\b(gila|best|padu|mantap|hahaha|lol)\b/i.test(text)) score += 2;
  }

  return score;
}

function pickPersonaSnippets(input) {
  const all = input.persona_snippets ?? input.cfg?.persona_snippets ?? [];
  if (!Array.isArray(all) || !all.length) return { persona_snippets: [], persona_fragment: '' };

  const tone = input.tone || 'gaul';
  const product = input.product || input.product_data || {};
